void main() {
  const generator = RankedProblemGenerator();
  final cases = (jsonDecode(_serverVectors) as List<dynamic>).cast<Map<String, dynamic>>();

  test('기준값이 비어 있지 않다', () {
    expect(cases, hasLength(120));
    expect(
      cases.fold<int>(0, (sum, c) => sum + (c['p'] as List<dynamic>).length),
      greaterThan(1000),
    );
  });

  group('랭크전 문제 생성이 서버와 완전히 같다', () {
    for (final testCase in cases) {
      final seed = testCase['s'] as int;
      final level = testCase['l'] as int;
      final count = testCase['c'] as int;
      final expected = (testCase['p'] as List<dynamic>).cast<List<dynamic>>();

      test('seed=$seed level=$level', () {
        final actual = generator.generateSession(seed: seed, level: level, count: count);

        expect(actual, hasLength(count));
        for (var i = 0; i < count; i++) {
          expect(
            actual[i].prompt,
            expected[i][0] as String,
            reason: 'seed=$seed level=$level index=$i 문제가 서버와 다릅니다',
          );
          expect(
            actual[i].answer,
            expected[i][1] as int,
            reason: 'seed=$seed level=$level index=$i 정답이 서버와 다릅니다',
          );
          expect(actual[i].index, i);
          expect(actual[i].level, level);
        }
      });
    }
  });

  test('같은 시드는 항상 같은 문제를 만든다', () {
    final first = generator.generateSession(seed: 4242, level: 7, count: 16);
    final second = generator.generateSession(seed: 4242, level: 7, count: 16);
    for (var i = 0; i < first.length; i++) {
      expect(first[i].prompt, second[i].prompt);
      expect(first[i].answer, second[i].answer);
    }
  });

  test('문제 수가 달라지면 시드가 같아도 다른 문제가 나온다', () {
    // 서버가 count를 시드에 섞기 때문입니다. 클라이언트가 서버에서 받은
    // problemCount를 그대로 쓰지 않으면 전부 오답 처리됩니다.
    final ten = generator.generateSession(seed: 4242, level: 7, count: 10);
    final sixteen = generator.generateSession(seed: 4242, level: 7, count: 16);
    expect(ten.first.prompt, isNot(sixteen.first.prompt));
  });
}
